CREATE TABLE `accommodation` (
  `AccommodationID` int unsigned NOT NULL AUTO_INCREMENT,
  `Name` varchar(200) COLLATE utf8mb4_general_ci NOT NULL,
  `Type` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `StarRating` tinyint unsigned DEFAULT NULL,
  `AveragePricePerNight` decimal(10,2) NOT NULL,
  `Description` text COLLATE utf8mb4_general_ci,
  `Street` varchar(200) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `City` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `Country` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`AccommodationID`),
  KEY `idx_price_star` (`AveragePricePerNight`,`StarRating`),
  CONSTRAINT `accommodation_chk_1` CHECK ((`StarRating` between 1 and 5)),
  CONSTRAINT `accommodation_chk_2` CHECK ((`AveragePricePerNight` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=6023 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
