--
-- Table structure for table `booking`
--

DROP TABLE IF EXISTS `booking`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `booking` (
  `BookingID` int unsigned NOT NULL AUTO_INCREMENT,
  `TravellerID` int unsigned NOT NULL,
  `PackageID` int unsigned NOT NULL,
  `Date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `NumberOfPeople` tinyint unsigned NOT NULL DEFAULT '1',
  `Status` enum('Pending','Confirmed','Cancelled','Completed') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'Pending',
  `TotalPrice` decimal(12,2) NOT NULL,
  PRIMARY KEY (`BookingID`),
  KEY `fk_booking_traveller` (`TravellerID`),
  KEY `fk_booking_package` (`PackageID`),
  CONSTRAINT `fk_booking_package` FOREIGN KEY (`PackageID`) REFERENCES `package` (`PackageID`),
  CONSTRAINT `fk_booking_traveller` FOREIGN KEY (`TravellerID`) REFERENCES `traveller` (`TravellerID`),
  CONSTRAINT `booking_chk_1` CHECK ((`NumberOfPeople` >= 1)),
  CONSTRAINT `booking_chk_2` CHECK ((`TotalPrice` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=31 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
