DROP TABLE IF EXISTS `flight`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `flight` (
  `FlightID` int unsigned NOT NULL AUTO_INCREMENT,
  `FlightNumber` varchar(20) COLLATE utf8mb4_general_ci NOT NULL,
  `Airline` varchar(150) COLLATE utf8mb4_general_ci NOT NULL,
  `DepartureDateTime` datetime NOT NULL,
  `ArrivalDateTime` datetime NOT NULL,
  `BaseCost` decimal(10,2) NOT NULL,
  `OriginAirportID` int unsigned NOT NULL,
  `DestinationAirportID` int unsigned NOT NULL,
  PRIMARY KEY (`FlightID`),
  KEY `fk_flight_origin` (`OriginAirportID`),
  KEY `fk_flight_destination` (`DestinationAirportID`),
  CONSTRAINT `fk_flight_destination` FOREIGN KEY (`DestinationAirportID`) REFERENCES `airport` (`AirportID`),
  CONSTRAINT `fk_flight_origin` FOREIGN KEY (`OriginAirportID`) REFERENCES `airport` (`AirportID`),
  CONSTRAINT `chk_flight_dates` CHECK ((`ArrivalDateTime` > `DepartureDateTime`)),
  CONSTRAINT `flight_chk_1` CHECK ((`BaseCost` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=5016 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

