CREATE TABLE `package` (
  `PackageID` int unsigned NOT NULL AUTO_INCREMENT,
  `AgencyID` int unsigned NOT NULL,
  `Title` varchar(300) COLLATE utf8mb4_general_ci NOT NULL,
  `Description` text COLLATE utf8mb4_general_ci,
  `StartDate` date NOT NULL,
  `EndDate` date NOT NULL,
  `MaxParticipants` int unsigned NOT NULL DEFAULT '1',
  `TotalPrice` decimal(10,2) NOT NULL,
  PRIMARY KEY (`PackageID`),
  KEY `fk_package_agency` (`AgencyID`),
  CONSTRAINT `fk_package_agency` FOREIGN KEY (`AgencyID`) REFERENCES `agency` (`AgencyID`) ON DELETE CASCADE,
  CONSTRAINT `chk_package_dates` CHECK ((`EndDate` > `StartDate`)),
  CONSTRAINT `package_chk_1` CHECK ((`TotalPrice` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `package`
--

LOCK TABLES `package` WRITE;
/*!40000 ALTER TABLE `package` DISABLE KEYS */;
INSERT INTO `package` VALUES (1,1,'Cape Town City & Coast Explorer','A 5-day journey through Cape Towns iconic landmarks, beaches and cuisine.','2026-06-01','2026-06-05',10,12000.00),(2,1,'Ultimate Cape Town Coastal Escape','A 7-day coastal getaway with wine tasting, Table Mountain and V&A Waterfront dining.','2026-06-15','2026-06-22',12,14500.00),(3,2,'Wild Kruger Luxury Safari','Experience the Big Five with 5 nights in a luxury lodge and expert guided game drives.','2026-07-01','2026-07-06',8,22000.00),(4,3,'Parisian Romance & Culture','A curated 5-day tour of the Louvre, Eiffel Tower and hidden bistros in Montmartre.','2026-09-10','2026-09-15',10,35000.00),(5,4,'Ubud Zen & Wellness Escape','Rejuvenate with daily yoga, spa treatments and rice terrace walks over 8 days in Bali.','2026-08-20','2026-08-28',15,18500.00),(6,1,'Winelands Wellness & Spa Retreat','A 5-day luxury escape in Stellenbosch with vineyard tours, spa treatments and fine dining.','2026-08-10','2026-08-15',6,18900.00),(7,2,'Drakensberg Royal Natal Hike','A 5-day guided hiking expedition to Tugela Falls and the Amphitheatre.','2026-10-12','2026-10-17',10,11500.00),(8,5,'Durban Culture & Coast','Explore Durban\'s Golden Mile, taste authentic bunny chow and dive into Zulu heritage over 4 days.','2026-07-15','2026-07-19',20,7800.00),(9,3,'Masai Mara Migration Safari','Witness the Great Wildebeest Migration on a 7-day Kenya safari with luxury tented camp stays.','2026-10-01','2026-10-07',10,38000.00),(10,4,'Mauritius Tropical Paradise','An all-inclusive 7-day retreat on the pristine lagoons of northern Mauritius.','2026-11-10','2026-11-17',16,29500.00),(11,5,'Soweto & Joburg Heritage Tour','A 3-day cultural immersion covering the Hector Pieterson Museum, Vilakazi Street and Gold Reef City.','2026-09-05','2026-09-08',25,6200.00),(12,1,'Garden Route Grand Drive','A 6-day self-drive adventure from Cape Town through Knysna to Port Elizabeth along the Garden Route.','2026-07-15','2026-07-21',14,9800.00),(13,2,'Cape Town & Winelands Combo','Combine two iconic Western Cape experiences: Cape Town city and the Stellenbosch Winelands in 5 days.','2026-08-01','2026-08-06',12,16500.00),(14,7,'Knysna Lagoon & Garden Route','A relaxed 5-day stay in Knysna with lagoon cruises, forest hikes and seafood feasts.','2026-07-10','2026-07-15',10,12400.00),(15,7,'Cape Peninsula Full Explorer','Discover Cape Point, Boulders Beach penguins and Clifton on this 4-day Cape adventure.','2026-08-03','2026-08-07',12,10800.00),(16,8,'Joburg City & Soweto Immersion','A 3-day urban experience covering the Apartheid Museum, Gold Reef City and authentic township dining.','2026-09-01','2026-09-04',20,7500.00),(17,8,'Pilanesberg Big Five Weekend','A 3-day malaria-free Big Five safari from Johannesburg, perfect for families.','2026-10-03','2026-10-06',16,11200.00),(18,9,'Durban Luxury Beachfront Break','Indulge in 4 days on Durban\'s Golden Mile with spa treatments and fine coastal dining.','2026-07-20','2026-07-24',8,13500.00),(19,9,'KZN Mountains & Coast Combo','Combine the uKhahlamba Drakensberg peaks with Durban\'s warm Indian Ocean in one 7-day itinerary.','2026-10-15','2026-10-22',14,17800.00),(20,10,'Drakensberg Peaks & Valleys','Five days of guided trails, abseiling and stargazing in the Southern Berg.','2026-09-20','2026-09-25',10,9600.00),(21,10,'Hermanus Whale Season Getaway','A 3-day coastal escape timed for peak southern right whale sightings on Walker Bay.','2026-09-12','2026-09-15',8,8900.00),(22,11,'Victoria Falls Adventure','Experience the might of the falls, a sunset Zambezi cruise and optional white-water rafting over 5 days.','2026-08-15','2026-08-20',12,26500.00),(23,11,'Zanzibar Island Escape','A 7-day tropical retreat combining Stone Town culture with spice farm tours and beach relaxation.','2026-11-01','2026-11-08',10,22000.00),(24,12,'Kalahari Desert & Stargazing','Explore the red dunes of the Kalahari and witness unrivalled night skies on this 4-day desert adventure.','2026-07-25','2026-07-29',8,14200.00),(25,12,'Addo Elephant & PE City Break','Three nights in Addo Elephant Park paired with a day exploring Port Elizabeth\'s historic city centre.','2026-08-10','2026-08-13',12,13600.00);
/*!40000 ALTER TABLE `package` ENABLE KEYS */;
UNLOCK TABLES;

