CREATE TABLE `traveller` (
  `TravellerID` int unsigned NOT NULL AUTO_INCREMENT,
  `FirstName` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `Surname` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `Email` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `Password` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `Phone` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `Nationality` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `DateOfBirth` date DEFAULT NULL,
  `JoinDate` date NOT NULL DEFAULT (curdate()),
  PRIMARY KEY (`TravellerID`),
  UNIQUE KEY `Email` (`Email`),
  CONSTRAINT `chk_traveller_email` CHECK ((`Email` like _utf8mb4'%@%.%'))
) ENGINE=InnoDB AUTO_INCREMENT=27 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
